import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import API from "../services/api";
import Zoom from "react-medium-image-zoom";
import "react-medium-image-zoom/dist/styles.css";
// Importar iconos para evitar el error de "Feather is not defined"
import { ArrowLeft, Heart, MessageCircle, FileText, Activity } from "lucide-react"; 
import "./ProductoDetalle.css";

function ProductoDetalle() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [producto, setProducto] = useState(null);
  const usuario = JSON.parse(localStorage.getItem("usuario"));

  useEffect(() => {
    cargarProducto();
  }, []);

  const cargarProducto = async () => {
    try {
      const res = await API.get(`/productos/${id}`);
      setProducto(res.data);
    } catch (error) {
      console.log("Error cargando producto", error);
    }
  };

  const agregarFavorito = async () => {
    try {
      const res = await API.post("/favoritos", {
        id_usuario: usuario.id_usuario,
        id_producto: producto.id_producto
      });
      alert(res.data.mensaje);
    } catch (error) {
      alert("Error agregando favorito");
    }
  };

  const comprarProducto = async () => {
    try {
      const res = await API.post("/comprar", { id_producto: producto.id_producto });
      alert(res.data.mensaje);
      cargarProducto();
    } catch (error) {
      alert("Error en la compra");
    }
  };

  if (!producto) return <div className="loading-state">Cargando pieza exclusiva...</div>;

  return (
    <div className="detalle-premium-wrapper">
      <div className="container-main">
        <button className="btn-back-minimal" onClick={() => navigate(-1)}>
          <ArrowLeft size={20} /> Volver al Catálogo
        </button>

        <div className="detalle-grid-premium">
          {/* LADO IZQUIERDO: VISUALES */}
          <div className="visuals-column">
            <div className="main-gem-card">
              <Zoom>
                <img
                  src={`http://localhost:3000/uploads/${producto.imagen}`}
                  alt={producto.tipo_producto}
                  className="gem-display-img"
                />
              </Zoom>
            </div>

            <div className="certificate-card">
              <div className="card-header-mini">
                <FileText size={18} color="#0f5f45" />
                <h3>Certificado de Autenticidad</h3>
              </div>
              <div className="cert-zoom-wrapper">
                <Zoom>
                  <img
                    src={`http://localhost:3000/uploads/${producto.certificado}`}
                    alt="Certificado"
                    className="cert-img-small"
                  />
                </Zoom>
              </div>
            </div>
          </div>

          {/* LADO DERECHO: DATOS */}
          <div className="info-column-premium">
            <div className="info-header">
              <span className="category-label">{producto.tipo_producto} Genuina</span>
              <h1 className="gem-title">Esmeralda {producto.color}</h1>
              <p className="vendedor-name">Colección privada de: <b>{producto.vendedor}</b></p>
            </div>

            <div className="main-specs-row">
              <div className="spec-bubble">
                <label>Peso</label>
                <span>{producto.peso} ct</span>
              </div>
              <div className="spec-bubble">
                <label>Color</label>
                <span>{producto.color}</span>
              </div>
              <div className="spec-bubble">
                <label>Tratamiento</label>
                <span>{producto.tratamiento || "Natural"}</span>
              </div>
            </div>

            <div className="price-section-premium">
              <label>Valor de Adquisición</label>
              <h2 className="price-tag">${Number(producto.valor).toLocaleString()} <small>USD</small></h2>
              {producto.estado === "vendido" && (
                <div className="sold-status">
                   <Activity size={16} /> Pieza ya adquirida
                </div>
              )}
            </div>

            <div className="actions-grid">
              <button
                className={`btn-primary-gold ${producto.estado === "vendido" ? "disabled" : ""}`}
                onClick={comprarProducto}
                disabled={producto.estado === "vendido"}
              >
                {producto.estado === "vendido" ? "VENDIDO" : "ADQUIRIR AHORA"}
              </button>

              <div className="secondary-actions">
                <button className="btn-sec-white" onClick={agregarFavorito}>
                  <Heart size={18} /> Favorito
                </button>
                <button className="btn-sec-white" onClick={() => navigate(`/chat/${producto.id_vendedor}`)}>
                  <MessageCircle size={18} /> Contactar
                </button>
              </div>
            </div>

            {producto.tipo_producto === "joya" && (
              <div className="joya-specs-card">
                <h3>Composición de la Joya</h3>
                <div className="joya-grid">
                   <p><b>Oro:</b> {producto.oro}</p>
                   <p><b>Plata:</b> {producto.plata}</p>
                   <p><b>Oro Rosado:</b> {producto.oro_rosado}</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default ProductoDetalle;
